class Ra2RepairableTypeTest2{[DllImport("kernel32.dll")]static extern IntPtr OpenProcess(uint a,bool b,int p);[DllImport("kernel32.dll")]static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[]b,int n,out IntPtr r);[DllImport("kernel32.dll")]static extern bool WriteProcessMemory(IntPtr h,IntPtr a,byte[]b,int n,out IntPtr w);static void Main(string[]x){bool off=x.Length==1&&x[0]=="--off";var g=Process.GetProcessesByName("game")[0];IntPtr h=OpenProcess(0x438,false,g.Id);byte[]b=new byte[4];IntPtr n;uint obj=0x209F1290;ReadProcessMemory(h,new IntPtr(obj+0x418),b,4,out n);uint type=BitConverter.ToUInt32(b,0);ReadProcessMemory(h,new IntPtr(type+0xAD9),b,1,out n);byte old=b[0];byte val=off?(byte)0:(byte)1;byte[]wbuf={val};IntPtr w;if(!off&&old!=0){Console.WriteLine("UNEXPECTED_OLD={0}",old);return;}if(WriteProcessMemory(h,new IntPtr(type+0xAD9),wbuf,1,out w)&&w.ToInt64()==1)Console.WriteLine("TYPE_REPAIRABLE_{0} type=0x{1:X8} old={2} new={3}",off?"RESTORED":"ENABLED",type,old,val);else Console.WriteLine("WRITE_FAILED");}}
